import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"Historial","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Historial de búsqueda","slug":"_1-historial-de-busqueda","link":"#_1-historial-de-busqueda","children":[]},{"level":2,"title":"2. Historial de palabras clave","slug":"_2-historial-de-palabras-clave","link":"#_2-historial-de-palabras-clave","children":[]},{"level":2,"title":"3. Asociaciones de consulta","slug":"_3-asociaciones-de-consulta","link":"#_3-asociaciones-de-consulta","children":[]}],"relativePath":"es-ES/user-guide/settings/history.md","filePath":"es-ES/user-guide/settings/history.md","lastUpdated":1795268921000}`),a={name:`es-ES/user-guide/settings/history.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="historial" tabindex="-1">Historial <a class="header-anchor" href="#historial" aria-label="Permalink to “Historial”">​</a></h1><p>Las tres pestañas gestionan por separado los elementos abiertos, los términos de búsqueda y las asociaciones aprendidas.</p><h2 id="_1-historial-de-busqueda" tabindex="-1">1. Historial de búsqueda <a class="header-anchor" href="#_1-historial-de-busqueda" aria-label="Permalink to “1. Historial de búsqueda”">​</a></h2><p>Registra la frecuencia y la fecha de apertura de cada archivo, carpeta o aplicación desde los resultados.</p><ul><li><strong>Ordenación</strong>: cada apertura suma 1 punto, hasta un máximo de 10. La puntuación se reduce a la mitad cada 90 días. Con 3 puntos efectivos se opta a H3 y con 5 a H5. La búsqueda rápida asigna hasta 3 plazas H5 y 10 H3; la integrada, 1 y 3. La ventana completa no limita las plazas.</li><li><strong>Alcance</strong>: el uso permite adelantar resultados del mismo grado efectivo y prioridad. El orden de tipos de la búsqueda rápida puede reducir el grado de nombre exacto de archivos y carpetas; consulta <a href="./../search-syntax.html">Sintaxis de búsqueda</a>.</li><li><strong>Grupos integrados</strong>: los resultados de la carpeta actual y los globales se muestran por separado. Se omiten las rutas inexistentes.</li><li><strong>Gestión</strong>: filtra por palabra, elimina entradas, borra las de N usos o menos, o borra todas. La lista se actualiza al abrir algo desde otra ventana. Desactivar el registro impide añadir entradas nuevas; las existentes siguen actualizando frecuencia y fecha.</li></ul><h2 id="_2-historial-de-palabras-clave" tabindex="-1">2. Historial de palabras clave <a class="header-anchor" href="#_2-historial-de-palabras-clave" aria-label="Permalink to “2. Historial de palabras clave”">​</a></h2><p>Guarda la consulta original al ejecutar un resultado o una acción, o al abrir la ventana completa. Escribir y cerrar la búsqueda rápida no crea un registro.</p><ul><li>Usa <strong>Alt+Up / Alt+Down</strong> para recorrer consultas anteriores y <strong>Ctrl+Delete</strong> para eliminar la actual.</li><li>Permite filtrar, eliminar entradas, borrar todo o limpiar por número de usos. Tiene su propio interruptor: al desactivarlo, no se añaden términos nuevos, pero los existentes siguen acumulando usos.</li></ul><h2 id="_3-asociaciones-de-consulta" tabindex="-1">3. Asociaciones de consulta <a class="header-anchor" href="#_3-asociaciones-de-consulta" aria-label="Permalink to “3. Asociaciones de consulta”">​</a></h2><p>Guarda asociaciones <strong>consulta → ruta de destino</strong> separadas de la puntuación general de uso.</p><ul><li>Una asociación se activa después de abrir un resultado normal al menos <strong>3 veces</strong> con la misma consulta normalizada. Abrir un resultado recuperado solo por asociación no aumenta esa cuenta.</li><li>Se añade como máximo <strong>una</strong> asociación por consulta. Se excluyen los destinos de prioridad baja; los resultados recuperados solo por asociación van después de las coincidencias directas.</li><li>Filtra, elimina o borra asociaciones sin reiniciar las puntuaciones de uso de las rutas.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};